import Badge from "./Badge";
import Button from "./Button";

export default function Hero() {
  return (
    <section className="py-32 relative overflow-hidden">
      <div className="container mx-auto max-w-3xl">
        <div className="relative z-10">
          <Badge>Available for new opportunities</Badge>
          <h1 className="mt-6 text-4xl font-medium leading-tight">
            Systems that stay up.<br />Quietly powering products.
          </h1>
          <p className="mt-6 max-w-lg text-lg text-gray-600">
            I'm Vincent Odume, a backend-leaning software engineer focused on
            reliable APIs, pragmatic architecture, and turning complex systems
            into calm, maintainable code.
          </p>
          <div className="mt-8 flex gap-4">
            <Button variant="primary">View Projects</Button>
            <Button variant="outline">View Blog Posts</Button>
          </div>
        </div>
      </div>
    </section>
  );
}
