import { Project } from "../interfaces/project";
import Button from "./Button";

const projects: Project[] = [
  {
    title: "SR Luxuries Architecture",
    description: "E-commerce platform backend and inventory management system.",
    image:
      "https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&q=80&w=800",
  },
  {
    title: "Ciba Healthcare",
    description:
      "Secure web application for a wellness clinic spanning 4 U.S. states.",
    image:
      "https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&q=80&w=800",
  },
  {
    title: "LinkOrgNet API",
    description:
      "High-performance RESTful API and corporate data portal.",
    image:
      "https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&q=80&w=800",
  },
  {
    title: "CrowAfrica Infrastructure",
    description:
      "Scalable deployment architecture for a high‑converting ecommerce hub.",
    image:
      "https://images.unsplash.com/photo-1504868584819-f8e8b4b6d7e3?auto=format&fit=crop&q=80&w=800",
  },
];

export default function Projects() {
  return (
    <section className="py-24">
      <div className="container mx-auto max-w-4xl grid grid-cols-1 gap-12">
        <h2 className="text-sm font-semibold uppercase text-gray-500">
          Systems
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
          {projects.map((p) => (
            <div
              key={p.title}
              className="flex flex-col gap-4 cursor-pointer group"
            >
              <div
                className="bg-gray-100 rounded overflow-hidden border border-gray-200"
                style={{ aspectRatio: '4/3' }}
              >
                <img
                  src={p.image}
                  alt={p.title}
                  className="w-full h-full object-cover group-hover:opacity-80"
                />
              </div>
              <div>
                <h3 className="text-base font-medium text-gray-900">
                  {p.title}
                </h3>
                <p className="text-sm text-gray-500">{p.description}</p>
              </div>
            </div>
          ))}
        </div>
        <div className="mt-6">
          <Button variant="outline">View full systems gallery</Button>
        </div>
      </div>
    </section>
  );
}
